/* ================= EXACT NIF GLOBAL HEADER MATCH ================= */
.custom-site-header {
  background: #ffffff !important;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08) !important;
  position: sticky !important;
  top: 0 !important;
  z-index: 99999 !important;
  width: 100% !important;
  padding: 10px 0 !important;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif !important;
}

.custom-nav-container {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  max-width: 1400px !important;
  margin: 0 auto !important;
  padding: 0 25px !important;
  width: 100% !important;
}

.custom-nav-logo {
  display: flex !important;
  align-items: center !important;
  flex-shrink: 0 !important;
}

.custom-nav-logo img {
  height: 52px !important;
  max-height: 52px !important;
  width: auto !important;
  object-fit: contain !important;
}

.custom-nav-menu-wrap {
  display: flex !important;
  align-items: center !important;
  flex-grow: 1 !important;
  justify-content: center !important;
}

.custom-nav-menu {
  display: flex !important;
  align-items: center !important;
  list-style: none !important;
  margin: 0 !important;
  padding: 0 !important;
  gap: 22px !important;
}

.custom-nav-item {
  position: relative !important;
  list-style: none !important;
}

.custom-nav-link {
  color: #222222 !important;
  font-size: 15px !important;
  font-weight: 500 !important;
  text-decoration: none !important;
  padding: 8px 4px !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 5px !important;
  transition: color 0.2s ease !important;
}

.custom-nav-link:hover,
.custom-nav-item:hover > .custom-nav-link {
  color: #b23228 !important;
}

.custom-nav-link .arrow-down {
  display: inline-block !important;
  width: 0 !important;
  height: 0 !important;
  margin-left: 2px !important;
  vertical-align: middle !important;
  border-top: 4px solid #222222 !important;
  border-right: 4px solid transparent !important;
  border-left: 4px solid transparent !important;
  transition: transform 0.2s ease, border-top-color 0.2s ease !important;
}

.custom-nav-link:hover .arrow-down,
.custom-nav-item:hover .arrow-down {
  border-top-color: #b23228 !important;
  transform: rotate(180deg) !important;
}

/* Dropdown Menu */
.custom-dropdown-menu {
  display: none !important;
  position: absolute !important;
  top: 100% !important;
  left: 0 !important;
  background: #ffffff !important;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.12) !important;
  border-radius: 6px !important;
  min-width: 260px !important;
  padding: 8px 0 !important;
  margin: 0 !important;
  list-style: none !important;
  z-index: 100000 !important;
  border: 1px solid #ebebeb !important;
}

.custom-nav-item:hover .custom-dropdown-menu {
  display: block !important;
}

.custom-dropdown-item {
  display: block !important;
  padding: 9px 18px !important;
  color: #333333 !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  text-decoration: none !important;
  transition: background 0.2s, color 0.2s !important;
}

.custom-dropdown-item:hover {
  background: #fbf1f0 !important;
  color: #b23228 !important;
  padding-left: 22px !important;
}

/* Right Actions */
.custom-nav-actions {
  display: flex !important;
  align-items: center !important;
  gap: 15px !important;
  flex-shrink: 0 !important;
}

.btn-admission-open {
  background-color: #b23228 !important;
  color: #ffffff !important;
  font-size: 15px !important;
  font-weight: 600 !important;
  padding: 10px 22px !important;
  border-radius: 4px !important;
  text-decoration: none !important;
  display: inline-block !important;
  border: none !important;
  transition: background-color 0.2s, transform 0.2s !important;
  white-space: nowrap !important;
  letter-spacing: 0.3px !important;
}

.btn-admission-open:hover {
  background-color: #93251c !important;
  color: #ffffff !important;
  transform: translateY(-1px) !important;
}

.pdf-download-badge {
  display: inline-flex !important;
  align-items: center !important;
  text-decoration: none !important;
  transition: transform 0.2s !important;
}

.pdf-download-badge:hover {
  transform: scale(1.04) !important;
}

.pdf-download-badge img {
  height: 42px !important;
  width: auto !important;
  object-fit: contain !important;
  display: block !important;
}

/* Mobile Toggle */
.custom-nav-toggle {
  display: none !important;
  background: transparent !important;
  border: none !important;
  font-size: 26px !important;
  color: #222 !important;
  cursor: pointer !important;
  padding: 5px !important;
}

@media (max-width: 1100px) {
  .custom-nav-link {
    font-size: 14px !important;
    gap: 3px !important;
  }
  .custom-nav-menu {
    gap: 14px !important;
  }
  .btn-admission-open {
    padding: 8px 15px !important;
    font-size: 14px !important;
  }
}

@media (max-width: 991px) {
  .custom-nav-toggle {
    display: block !important;
  }
  .custom-nav-menu-wrap {
    display: none !important;
    position: absolute !important;
    top: 100% !important;
    left: 0 !important;
    right: 0 !important;
    background: #ffffff !important;
    box-shadow: 0 10px 20px rgba(0, 0, 0, 0.1) !important;
    padding: 20px !important;
    flex-direction: column !important;
  }
  .custom-nav-menu-wrap.show {
    display: flex !important;
  }
  .custom-nav-menu {
    flex-direction: column !important;
    align-items: flex-start !important;
    width: 100% !important;
    gap: 10px !important;
  }
  .custom-dropdown-menu {
    position: static !important;
    box-shadow: none !important;
    border: none !important;
    padding-left: 15px !important;
  }
  .custom-nav-actions {
    margin-top: 15px !important;
    width: 100% !important;
    justify-content: flex-start !important;
  }
}
